-- Biblioteca Inclusiva · Língua Inglesa do 9º ano completa.
WITH lessons(code,title,goal) AS (VALUES
('EF09LI01','Pontos de vista e argumentação oral','Expor tese, razões e evidências em formato acessível, sem debate público obrigatório.'),
('EF09LI02','Notas de textos orais','Registrar palavras-chave, tese, razões, evidências e contra-argumentos com organizador visual.'),
('EF09LI03','Análise de posicionamentos','Comparar argumentos e contra-argumentos sem coletar opinião política ou crença pessoal.'),
('EF09LI04','Apresentação de pesquisa','Apresentar método, amostra, dados e limites por fala opcional ou produto multimodal.'),
('EF09LI05','Recursos de persuasão','Analisar palavras, imagens, enquadramento, cor e tamanho usados para persuadir.'),
('EF09LI06','Fato e opinião','Distinguir afirmações verificáveis, interpretações e avaliações pessoais.'),
('EF09LI07','Argumentos e evidências','Avaliar pertinência, suficiência e relação entre tese, argumento e evidência.'),
('EF09LI08','Validade das fontes','Verificar autoria, instituição, data, referências, método, finalidade e conflitos de interesse.'),
('EF09LI09','Pesquisa para produção textual','Pesquisar em fontes seguras, registrar referências e selecionar informações relevantes.'),
('EF09LI10','Organização argumentativa','Ordenar tese, argumentos, evidências, contraponto e conclusão com conectores.'),
('EF09LI11','Recursos multimodais','Integrar texto, tabela, gráfico e imagem de forma acessível e sem manipulação.'),
('EF09LI12','Campanha ética','Criar campanha sobre situação fictícia ou coletiva usando evidência e circulação controlada.'),
('EF09LI13','Escrita digital e contexto','Interpretar abreviações, símbolos e pictogramas conforme público, gênero e propósito.'),
('EF09LI14','Conectores argumentativos','Usar conectores de adição, oposição, condição, conclusão e síntese.'),
('EF09LI15','Orações condicionais','Distinguir condições possíveis e hipotéticas em problemas fictícios.'),
('EF09LI16','Verbos modais','Expressar recomendação, obrigação, necessidade e probabilidade com precisão.'),
('EF09LI17','Expansão histórica do inglês','Analisar migração, comércio e colonialismo de modo histórico, informativo e não gráfico.'),
('EF09LI18','Inglês em ciência, economia e política','Avaliar usos internacionais do inglês e desigualdades de acesso sem apresentar uma língua como superior.'),
('EF09LI19','Inglês, identidades e multilinguismo','Debater língua, poder e identidade valorizando multilinguismo e direitos linguísticos.')
), normalized AS (
 SELECT code,'src/escola-brilha/ingles-9ano/bncc-workshops.ts'::text AS source_key,title,goal FROM lessons
)
